// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

class NativeTelemetryCounterTest {

	@Test
	void countsIncrementsAndAmountsAndCanBeReplaced() {
		NativeTelemetryCounter counter = new NativeTelemetryCounter();
		assertEquals(0L, counter.get());
		counter.increment();
		counter.add(41L);
		assertEquals(42L, counter.get());
		counter.set(0L);
		assertEquals(0L, counter.get());
		counter.set(7L);
		counter.increment();
		assertEquals(8L, counter.get());
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void losesNoUpdateOfConcurrentThreads() throws Exception {
		NativeTelemetryCounter counter = new NativeTelemetryCounter();
		int threads = 8;
		int rounds = 100_000;
		ExecutorService workers = Executors.newFixedThreadPool(threads);
		try {
			List<Future<?>> running = new ArrayList<>();
			for (int thread = 0; thread < threads; thread++) {
				running.add(workers.submit(() -> {
					for (int round = 0; round < rounds; round++) {
						counter.increment();
						counter.add(2L);
					}
				}));
			}
			for (Future<?> worker : running) {
				worker.get(25, TimeUnit.SECONDS);
			}
		} finally {
			workers.shutdownNow();
		}
		assertEquals(3L * threads * rounds, counter.get());
	}
}
